using System.Reflection;
using Path=System.IO.Path;
using System.Text.Json;
using System.Text.Json.Nodes;
using Comfort.Common;
using EFT;
using EFT.InventoryLogic;
using EFT.HealthSystem;
using EscapeFromBorderlands.Client;
using S=EscapeFromBorderlands.Server;
using UnityEngine;
using SPTarkov.Server.Core.Models.Eft.Common.Tables;
using SPTarkov.Server.Core.Utils.Json.Converters;
using Item=EFT.InventoryLogic.Item;
int cases=0,assertions=0,failures=0;
void Check(bool ok,string why){assertions++;if(!ok)throw new Exception(why);}
void Near(double a,double b,string why)=>Check(Math.Abs(a-b)<.0001,$"{why}: {a} != {b}");
void Run(string name,Action test){cases++;try{ChestRigRuntime.Reset();ProjectileEffectSpawner.ResetSession();LegendaryRuntime.Applications.Clear();ProjectileTestEvents.Reset();RarityResolver.ResetSession();Time.time=100;BackpackRuntime.Day=true;BackpackRuntime.CarriedFactors.Clear();test();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+(e.InnerException??e));}}
var client=LegendaryCatalog.Load();var server=S.LegendaryCatalog.Load();
var rigs=client.Variants.Where(v=>v.ChestRigEffect!=null).ToArray();var concrete=rigs.Where(v=>!v.IsMysteryFleaOffer).ToArray();
var main=concrete.Where(v=>v.StorageRows==0&&v.StorageColumns==0).ToArray();
var options=new JsonSerializerOptions{Converters={new StringToMongoIdConverter()}};
(Player P,Weapon W,ChestRigRuntime.State S) Equip(string key,string klass="assaultRifle",int count=30){var d=main.Single(v=>v.RuntimeKey==key);var p=new Player();p.InventoryController.Player=p;var rig=new CompoundItem{StringTemplateId=d.TemplateId,Owner=p};p.InventoryController.Inventory.Equipment.GetSlot(EquipmentSlot.TacticalVest).ContainedItem=rig;var w=new Weapon{Owner=p,WeapClass=klass,Magazine=new(){Count=count,MaxCount=count}};p.InventoryController.Inventory.Equipment.GetSlot(EquipmentSlot.FirstPrimaryWeapon).ContainedItem=w;p.HandsController=new Player.FirearmController{Item=w,Player=p};var world=new GameWorld();world.RegisteredPlayers.Add(p);Singleton<GameWorld>.Instance=world;ChestRigRuntime.Maintain(world);var s=ChestRigRuntime.Get(p)!;var b=s.Roll.ChestRig;b.Movement=b.Aim=b.AimCost=b.ChamberCheck=b.Ergonomics=b.FrameWeight=b.MagazineCheck=b.Packing=b.Recoil=b.Reload=b.Swap=1;return(p,w,s);}
void Tick(float seconds=.11f){Time.time+=seconds;ChestRigRuntime.Maintain(Singleton<GameWorld>.Instance);}
Ammo Ammo(string id="round",int pellets=1)=>new(){StringTemplateId=id,AmmoTemplate=new(){ProjectileCount=pellets}};
ChestRigRuntime.ShotScope Fire(Player p,Weapon w,Ammo? ammo=null,bool? hit=null){if(w.Magazine!=null&&w.Magazine.Count>0)w.Magazine.Count--;var s=ChestRigRuntime.Begin(w,ammo??Ammo(),p)!;var shot=new Shot{Weapon=w,FireIndex=s.Ordinal};ChestRigRuntime.Associate(shot);ChestRigRuntime.End(s);if(hit==true)ChestRigRuntime.FleshHit(s,new Player(),EBodyPart.Chest,false);if(hit.HasValue){ChestRigRuntime.BulletFinished(shot);Tick();}return s;}
void Put(Player p,EquipmentSlot slot,Item? item)=>p.InventoryController.Inventory.Equipment.GetSlot(slot).ContainedItem=item;
TemplateItemProperties Shape(params (int W,int H)[] grids){var n=new JsonObject{["Width"]=2,["Height"]=3,["GridLayoutName"]="fixed-rig",["Grids"]=new JsonArray(grids.Select((d,i)=>(JsonNode)new JsonObject{["_id"]=i.ToString("x24"),["_name"]="grid"+i,["_parent"]="aaaaaaaaaaaaaaaaaaaaaaaa",["_props"]=new JsonObject{["cellsH"]=d.W,["cellsV"]=d.H,["filters"]=new JsonArray()}}).ToArray())};var result=n.Deserialize<TemplateItemProperties>(options)!;foreach(var p in typeof(TemplateItemProperties).GetProperties().Where(p=>p.PropertyType==typeof(string)&&p.CanRead&&p.CanWrite&&p.GetIndexParameters().Length==0))if(p.GetValue(result)==null)p.SetValue(result,"");return result;}
JsonObject Node(TemplateItemProperties p)=>JsonSerializer.SerializeToNode(p,options)!.AsObject();
(int,int) Size(JsonObject n,int i)=>(n["Grids"]![i]!["_props"]!["cellsH"]!.GetValue<int>(),n["Grids"]![i]!["_props"]!["cellsV"]!.GetValue<int>());
Run("Approved scope: 88 signatures, 57 vanilla rigs, four owned layouts and one stock identity",()=>{Check(main.Length==88&&main.Select(d=>d.SourceTemplateId).Distinct().Count()==57,"workbook scope");Check(concrete.Length==352&&rigs.Count(v=>v.IsMysteryFleaOffer)==88,"complete storage families");Check(client.Variants.Count==server.Variants.Count,"matching catalogs");Check(client.Variants.Select(v=>v.TemplateId).Distinct().Count()==client.Variants.Count,"unique template IDs");Check(main.Select(v=>v.ShortName).Distinct().Count()==88,"unique rig names");foreach(var d in rigs){Check(d.AffixCount==4&&d.Tier=="Legendary"&&d.BackgroundColor=="orange","rarity and boons");Check(server.Variants.Single(s=>s.TemplateId==d.TemplateId).EffectText==d.EffectText,"identical descriptions");}});
Run("Four distinct eligible boons are deterministic for every owned rig",()=>{foreach(var d in concrete){var fingerprints=new HashSet<string>();for(int i=0;i<100;i++){var item=new Item{Id="test-"+i+"-"+d.TemplateId,StringTemplateId=d.TemplateId};var r=RarityResolver.Resolve(item)!;Check(r.AffixDescriptions.Count==5&&r.AffixDescriptions[0]==d.EffectText,"signature plus four boons");Check(r.AffixDescriptions.Skip(1).Select(s=>s.Split(' ')[0]).Distinct().Count()==4,"four distinct choices");Check(r.AffixDescriptions.Count(s=>s.StartsWith("Expanded Pouch"))==d.StorageRows,"row matches stored geometry");Check(r.AffixDescriptions.Count(s=>s.StartsWith("Widened Pouch"))==d.StorageColumns,"column matches stored geometry");Check(!r.ChestRig.RemoveTurningPenalty||d.ChestRigEffect!.HasTurningPenalty,"no useless harness roll");var text=string.Join("|",r.AffixDescriptions);RarityResolver.ResetSession();Check(string.Join("|",RarityResolver.Resolve(item)!.AffixDescriptions)==text,"same persisted ID same roll");fingerprints.Add(text);}Check(fingerprints.Count>1,"individual variation");}});
Run("Mystery rig stock shows four unknown boons and a visible cyan signature",()=>{foreach(var d in rigs.Where(v=>v.IsMysteryFleaOffer)){var roll=RarityResolver.Resolve(new Item{StringTemplateId=d.TemplateId})!;Check(roll.AffixDescriptions.Skip(1).SequenceEqual(new[]{"????","????","????","????"}),"unrevealed boons");Check(roll.BuildDescriptionBlock().Contains("#66D9EF"),"signature highlight");Check(d.SpawnWeight==0&&!d.SpawnEnabled,"stock never spawns");}});
Run("Storage layout weights match uniform four-of-N selection",()=>{foreach(var family in concrete.GroupBy(v=>v.StorageFamilyId)){var n=family.First().ChestRigEffect!.HasTurningPenalty?13d:12d;var sum=family.Sum(v=>v.SpawnWeight);Near(family.Where(v=>v.StorageRows>0).Sum(v=>v.SpawnWeight)/sum,4/n,"row marginal");Near(family.Where(v=>v.StorageColumns>0).Sum(v=>v.SpawnWeight)/sum,4/n,"column marginal");Near(family.Where(v=>v.StorageRows>0&&v.StorageColumns>0).Sum(v=>v.SpawnWeight)/sum,12/(n*(n-1)),"joint marginal");}});
Run("Rigs extend the largest original grid without touching shared source templates",()=>{foreach(var d in server.Variants.Where(v=>v.ChestRigEffect!=null&&!v.IsMysteryFleaOffer)){var original=Shape((1,2),(4,4),(2,2));var before=Node(original).ToJsonString();var result=Node(S.ChestRigStorage.Apply(original,d.ChestRigEffect!,d.TemplateId));Check(Node(original).ToJsonString()==before,"source immutability");var all=d.ChestRigEffect!.EveryGridColumns;var rows=d.ChestRigEffect!.EveryGridRows;Check(Size(result,0)==(1+all,2+rows),"small pocket unchanged except flat pack");Check(Size(result,1)==(4+all+d.StorageColumns,4+rows+d.StorageRows),"largest grid receives random capacity");Check(Size(result,2)==(2+all,2+rows),"other pocket preserved");Check(result["Grids"]!.AsArray().Count==3+d.ChestRigEffect.ExtraGrids.Count,"signature grid appended");foreach(var e in d.ChestRigEffect.ExtraGrids){var filters=result["Grids"]![3]!["_props"]!["filters"]![0]!["Filter"]!.AsArray();Check(filters.Count==e.Filter.Count,"restricted extra grid");}}});
Run("Chest-rig pool target remains aggregate 1% despite hundreds of clone templates",()=>{var variants=server.Variants.Where(v=>v.ChestRigEffect!=null&&v.SpawnEnabled).ToArray();var original=new Dictionary<string,double>{{main[0].SourceTemplateId,100},{"other-mod",300}};var families=variants.GroupBy(v=>v.SourceTemplateId).ToDictionary(g=>g.Key,g=>g.Select(v=>v.TemplateId).ToArray());var weights=variants.ToDictionary(v=>v.TemplateId,v=>v.SpawnWeight);var added=S.CategorySpawnPolicy.Weights(original,families,.01,weights);var sum=added.Values.Sum();Near(sum/(400+sum),.01,"aggregate probability");Check(added.Keys.All(k=>variants.Any(v=>v.TemplateId==k&&v.SourceTemplateId==main[0].SourceTemplateId)),"natural sources only");Check(S.CategorySpawnPolicy.Weights(original,families,0,weights).Count==0,"zero really disables category");Near(original["other-mod"],300,"other mods unchanged");});
Run("Per-category F12 visibility covers all sixteen combinations without modifying statuses",()=>{var statuses=new[]{new EffectStatusModel.Status("gun:x","Gun",true,10),new("melee:x","Knife",true,11),new("BP1-1","Bag",true,12),new("rig:TR1-1","Rig",false,0,13)};for(int mask=0;mask<16;mask++){var a=statuses.Where(s=>StatusVisibility.Allows(s.Key,(mask&1)!=0,(mask&2)!=0,(mask&4)!=0,(mask&8)!=0)).ToArray();Check(a.Length==System.Numerics.BitOperations.PopCount((uint)mask),"independent visibility");Check(statuses[0].Seconds==10&&statuses[3].Ready==13,"no timers changed");}Check(StatusVisibility.Allows("gun-smoke:x",true,false,false,false),"gun smoke belongs to gun option");});
Run("F12 visibility never consumes charges or stops rig gameplay",()=>{var(p,w,s)=Equip("AR27-2");s.Weapon(w).Selector=true;for(int i=0;i<100;i++)foreach(var status in ChestRigRuntime.Statuses(p))_=StatusVisibility.Allows(status.Key,false,true,false,false);Check(s.Weapon(w).Selector,"hidden status retains charge");Near(Fire(p,w).Bonuses.Damage,2,"hidden signature still applies");Check(!s.Weapon(w).Selector,"firing consumes once");});
Run("Chamber bonuses activate immediately after reload and end on that firearm's next reload",()=>{var(p,w,s)=Equip("TR03-1");ChestRigRuntime.ReloadCompleted(p,w,false);ChestRigRuntime.Check(p,w,1);Near(ChestRigRuntime.Preview(s,w,Ammo()).Velocity,1.4,"no pending reload clears new check");Near(ChestRigRuntime.Noise(p,"movement"),.6,"noise active with held checked gun");Fire(p,w);Near(ChestRigRuntime.Preview(s,w,Ammo()).Velocity,1.4,"full magazine persistence");ChestRigRuntime.ReloadCompleted(p,w,false);Near(ChestRigRuntime.Preview(s,w,Ammo()).Velocity,1,"reload removes");});
Run("Stripper's Union excludes shotguns and pistols even with internal magazines",()=>{foreach(var klass in new[]{"sniperRifle","assaultRifle","assaultCarbine","marksmanRifle","shotgun","pistol"}){var(p,w,s)=Equip("TR27-2",klass);w.ReloadMode="InternalMagazine";ChestRigRuntime.Check(p,w,1);Near(ChestRigRuntime.Preview(s,w,Ammo()).Penetration,klass is "shotgun" or "pistol"?1:1.4,"rifles only");}});
Run("Minimum Fuss includes chamber capacity and rejects eleven rounds",()=>{var(p,w,s)=Equip("AR17-1",count:9);w.Chambers=1;ChestRigRuntime.Check(p,w,1);Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1.4,"ten including chamber");w.Magazine!.MaxCount=10;Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1,"eleven excluded");});
Run("Midnight Drill lasts five seconds, survives reloads and retains its cooldown",()=>{var(p,w,s)=Equip("TR04-2");ChestRigRuntime.Check(p,w,2);Near(ChestRigRuntime.ReloadSpeed(s,w),1,"day does not arm");BackpackRuntime.Day=false;ChestRigRuntime.Check(p,w,2);Near(ChestRigRuntime.ReloadSpeed(s,w),1.75,"night bonus");ChestRigRuntime.ReloadCompleted(p,w,false);Near(ChestRigRuntime.ReloadSpeed(s,w),1.75,"reload does not consume timed effect");Time.time+=4.999f;Near(ChestRigRuntime.ReloadSpeed(s,w),1.75,"active before boundary");Time.time=105;Near(ChestRigRuntime.ReloadSpeed(s,w),1,"expires exactly at five seconds");ChestRigRuntime.Check(p,w,2);Near(ChestRigRuntime.ReloadSpeed(s,w),1,"cooldown blocks rearm");Put(p,EquipmentSlot.TacticalVest,null);Check(ChestRigRuntime.Statuses(p).Any(x=>x.Ready>0&&!x.Active),"cooldown visible after removal");});
Run("Fresh Hands and Patrol Route restore bounded Arm/Leg Stamina",()=>{var(p,w,s)=Equip("TR14-2");p.Physical.HandsStamina.Current=10;ChestRigRuntime.Check(p,w,2);Near(p.Physical.HandsStamina.Current,50,"arm restoration");ChestRigRuntime.Check(p,w,2);Near(p.Physical.HandsStamina.Current,50,"no cooldown bypass");var q=Equip("TR26-2");q.P.Physical.Stamina.Current=0;q.S.PatrolCharged=true;ChestRigRuntime.Check(q.P,q.W,2);Near(q.P.Physical.Stamina.Current,50,"patrol restoration");Check(!q.S.PatrolCharged&&q.S.WalkDistance==0,"single package consumed");});
Run("Last Resort arms once on empty primary and retains exactly three secondary shots",()=>{var(p,w,s)=Equip("TR10-1",count:1);var pistol=new Weapon{Owner=p,WeapClass="pistol",Magazine=new(){Count=10,MaxCount=10}};Put(p,EquipmentSlot.Holster,pistol);Fire(p,w);Check(s.EmptyPrimary,"empty through firing");p.HandsController=new Player.FirearmController{Item=pistol};ChestRigRuntime.Draw(s,pistol);for(int i=0;i<3;i++)Near(Fire(p,pistol).Bonuses.Damage,1.5,"three empowered shots");Near(Fire(p,pistol).Bonuses.Damage,1,"fourth normal");ChestRigRuntime.Draw(s,w);ChestRigRuntime.Draw(s,pistol);Near(s.Weapon(pistol).Charges,0,"redraw no replenishment");});
Run("Flash Course and Vine Swing snapshot their third charge before consuming it",()=>{var(p,w,s)=Equip("TR11-2");s.Weapon(w).Charges=3;for(int i=0;i<3;i++){var shot=Fire(p,w);Near(shot.Bonuses.Hip,.4,"third hip shot still empowered");}Near(Fire(p,w).Bonuses.Hip,1,"fourth normal");var q=Equip("TR24-1");q.S.GlobalShots=3;for(int i=0;i<3;i++)Near(Fire(q.P,q.W).Bonuses.Recoil,.5,"three recoil shots");Near(Fire(q.P,q.W).Bonuses.Recoil,1,"fourth normal");});
Run("Aimed Flash Course shots spend charges without hip-fire benefit",()=>{var(p,w,s)=Equip("TR11-2");s.Weapon(w).Charges=1;p.HandsController!.IsAiming=true;Near(Fire(p,w).Bonuses.Hip,1,"aimed no hip bonus");Check(s.Weapon(w).Charges==0,"charge consumed");});
Run("Handloader counts actual manually packed cartridges across magazines",()=>{var(p,w,s)=Equip("TR15-1");for(int i=0;i<9;i++)ChestRigInventory.Packed(p.InventoryController);Check(s.HandloadShots==0,"nine insufficient");ChestRigInventory.Packed(p.InventoryController);Check(s.HandloadShots==5&&s.Packing==0,"ten arms five");for(int i=0;i<5;i++)Near(Fire(p,w).Bonuses.Damage,1.25,"five buffed");Near(Fire(p,w).Bonuses.Damage,1,"sixth normal");});
Run("Three-Lane Traffic and Channel Surfing hold one nonstacking next-shot charge",()=>{var(p,w,s)=Equip("TR15-2");ChestRigRuntime.Draw(s,w);Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1,"same gun no charge");var other=new Weapon{Owner=p,Magazine=new()};ChestRigRuntime.Draw(s,other);ChestRigRuntime.Draw(s,w);Near(Fire(p,w).Bonuses.Damage,1.4,"switch package");Near(Fire(p,w).Bonuses.Damage,1,"spent");var q=Equip("AR27-2");ChestRigRuntime.ObserveMode(q.S,q.W);q.W.Mode="fullauto";ChestRigRuntime.ObserveMode(q.S,q.W);q.W.Mode="single";ChestRigRuntime.ObserveMode(q.S,q.W);Near(Fire(q.P,q.W).Bonuses.Damage,2,"repeated selector holds one");Near(Fire(q.P,q.W).Bonuses.Damage,1,"one shot only");});
Run("Pocket Rocket counts cartridges and respects the single-projectile ammunition gate",()=>{var(p,w,s)=Equip("TR21-2","pistol");for(int i=1;i<=8;i++)Check(Fire(p,w).Bonuses.DoubleExplosive==(i%4==0),"every fourth");ChestRigRuntime.ReloadCompleted(p,w,false);s.Weapon(w).Shots=3;Check(!Fire(p,w,Ammo(pellets:8)).Bonuses.DoubleExplosive,"no multiplier on buckshot");});
Run("Close Account gives a pistol-specific five-second reload bonus",()=>{var(p,w,s)=Equip("TR22-2","pistol",2);Near(Fire(p,w).Bonuses.Damage,1,"penultimate");Near(Fire(p,w).Bonuses.Damage,2,"last");Near(ChestRigRuntime.ReloadSpeed(s,w),1.75,"timed bonus");Near(ChestRigRuntime.ReloadSpeed(s,new Weapon()),1,"other firearm not boosted");ChestRigRuntime.ReloadCompleted(p,w,false);Near(ChestRigRuntime.ReloadSpeed(s,w),1.75,"timer survives reload");Time.time+=5;Near(ChestRigRuntime.ReloadSpeed(s,w),1,"expired");});
Run("Shell Game alternates actual ammunition identities and resets on reload",()=>{var(p,w,s)=Equip("TR28-1","shotgun");Near(Fire(p,w,Ammo("a")).Bonuses.Damage,1,"initial shell");Near(Fire(p,w,Ammo("b")).Bonuses.Damage,1.5,"changed shell");Near(Fire(p,w,Ammo("b")).Bonuses.Damage,1,"same shell");ChestRigRuntime.ReloadCompleted(p,w,false);Near(Fire(p,w,Ammo("a")).Bonuses.Damage,1,"reload establishes new baseline");});
Run("Burst cartridge counter ignores other modes and resets on reload",()=>{var(p,w,s)=Equip("TR31-1");w.Mode="burst";Near(Fire(p,w).Bonuses.Damage,1,"burst one");w.Mode="single";Fire(p,w);w.Mode="burst";Near(Fire(p,w).Bonuses.Damage,1,"burst two");Near(Fire(p,w).Bonuses.Damage,1.75,"burst three");ChestRigRuntime.ReloadCompleted(p,w,false);Near(Fire(p,w).Bonuses.Damage,1,"reset sequence");});
Run("Halfway House and Ready Reckoner use correct pre-shot capacity windows",()=>{var(p,w,s)=Equip("TR31-2",count:10);for(int i=0;i<6;i++)Fire(p,w);Near(ChestRigRuntime.Preview(s,w,Ammo()).FireRate,1.3,"crossed below half");ChestRigRuntime.ReloadCompleted(p,w,false);w.Magazine!.Count=10;Near(ChestRigRuntime.Preview(s,w,Ammo()).FireRate,1,"reset full");var q=Equip("TR32-1",count:10);for(int i=0;i<5;i++)Near(Fire(q.P,q.W).Bonuses.Recoil,.6,"first half recoil");Near(Fire(q.P,q.W).Bonuses.Damage,1.35,"at half damage");});
Run("Hard Count begins every-third additional shot after forty, not on shot forty",()=>{var(p,w,s)=Equip("AR20-2",count:100);for(int i=1;i<=50;i++)Near(Fire(p,w).Bonuses.Damage,i>40&&(i-40)%3==0?2:1,"ordinal "+i);ChestRigRuntime.ReloadCompleted(p,w,false);Near(Fire(p,w).Bonuses.Damage,1,"reload reset");});
Run("Frequency Hopping earns only after cartridges in both required modes",()=>{var(p,w,s)=Equip("AR28-2");w.Mode="burst";Fire(p,w);Check(!s.Weapon(w).Earned,"burst excluded");w.Mode="single";Fire(p,w);w.Mode="fullauto";Fire(p,w);var next=ChestRigRuntime.Preview(s,w,Ammo());Near(next.Damage,1.75,"damage earned");Near(next.FireRate,.5,"rate earned");ChestRigRuntime.ReloadCompleted(p,w,false);Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1,"reload clears both");});
Run("Volley siblings count one qualifying cartridge and out-of-order outcomes retain fire order",()=>{var(p,w,s)=Equip("AR04-1");var a=Fire(p,w);var b=Fire(p,w);ChestRigRuntime.FleshHit(b,new Player(),EBodyPart.Chest,false);Check(s.Weapon(w).Consecutive==0,"later hit waits for earlier outcome");ChestRigRuntime.FleshHit(a,new Player(),EBodyPart.Chest,false);Check(s.Weapon(w).Consecutive==2,"ordered hit sequence");ChestRigRuntime.FleshHit(a,new Player(),EBodyPart.Chest,false);Check(s.Weapon(w).Consecutive==2,"same cartridge not double counted");Fire(p,w,hit:false);Check(s.Weapon(w).Consecutive==0,"miss resets buildup");for(int i=0;i<4;i++)Fire(p,w,hit:true);Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1.25,"earned magazine buff");Fire(p,w,hit:false);Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1.25,"earned survives misses");ChestRigRuntime.ReloadCompleted(p,w,false);Near(ChestRigRuntime.Preview(s,w,Ammo()).Damage,1,"reload ends earned buff");});
Run("Flesh lookup survives impact dispatch before native health application",()=>{var(p,w,s)=Equip("AR04-1");var v=Fire(p,w);var bullet=new Shot{Weapon=w,FireIndex=123};ChestRigRuntime.CurrentShot=v;ChestRigRuntime.Associate(bullet);ChestRigRuntime.End(v);ChestRigRuntime.BulletFinished(bullet);Check(ChestRigRuntime.FindScope(w,123)==v,"impact record retained until health callback");ChestRigRuntime.FleshHit(v,new Player(),EBodyPart.Chest,false);Check(s.Weapon(w).Consecutive==1,"late native flesh confirmation");foreach(var pending in v.Pending.ToArray())ChestRigRuntime.BulletFinished(pending);Tick();Check(ChestRigRuntime.FindScope(w,123)==null,"finished volley cleaned");});
Run("Assault Ladder uses fire-time mode rather than mode selected when a distant bullet lands",()=>{var(p,w,s)=Equip("AR10-1");w.Mode="fullauto";var shots=Enumerable.Range(0,3).Select(_=>Fire(p,w)).ToArray();w.Mode="single";foreach(var shot in shots)ChestRigRuntime.FleshHit(shot,new Player(),EBodyPart.Chest,false);Check(s.Weapon(w).Earned,"three actual full-auto hits");});
Run("Reload generation rejects old projectiles from the previous magazine",()=>{var(p,w,s)=Equip("AR04-1");var old=Fire(p,w);ChestRigRuntime.ReloadCompleted(p,w,false);ChestRigRuntime.FleshHit(old,new Player(),EBodyPart.Chest,false);Check(s.Weapon(w).Consecutive==0&&!s.Weapon(w).Earned,"no stale magazine credit");});
Run("Static Charge, Counted Breath and Frontline Savings are one-shot snapshots",()=>{var(p,w,s)=Equip("TR11-1");s.Arm("static",100);var shot=Fire(p,w);Near(shot.Bonuses.Damage,1.5,"static damage");Near(shot.Bonuses.Velocity,1.6,"static velocity");Near(Fire(p,w).Bonuses.Damage,1,"one static shot");var q=Equip("TR29-2");q.S.BreathArmed=true;Near(Fire(q.P,q.W).Bonuses.Damage,1.4,"breath empowered");Check(!q.S.BreathArmed,"spent breath");var r=Equip("AR03-2");r.S.HitDamage=1.45f;Near(Fire(r.P,r.W).Bonuses.Damage,1.45,"blocked-hit savings");Near(Fire(r.P,r.W).Bonuses.Damage,1,"spent savings");});
