 Check(Convert.ToInt32(panel.Properties!.ArmorClass)==2,"source class2 unchanged");
 var pools=new Dictionary<SPTarkov.Server.Core.Models.Common.MongoId,Dictionary<string,HashSet<SPTarkov.Server.Core.Models.Common.MongoId>>>();f.Pools(pools,d);Check(pools[rig.Id].Count==3,"bot children use all three upgraded soft slots");
 f.Apply(rig,d);Check(f.databaseService.Items.Count==5,"repeat startup/layout processing does not duplicate panels");
