Run("Pocket Rocket runs the actual spawning pipeline and explodes both projectiles exactly once",()=>{
 var(p,w,s)=Equip("TR21-2","pistol");var calculator=Singleton<GameWorld>.Instance!.SharedBallisticsCalculator;
 var postfix=typeof(BallisticEffectPatch).GetMethod("Postfix",BindingFlags.NonPublic|BindingFlags.Static)!;
 for(int n=1;n<=4;n++){
  var ammo=Ammo();w.Magazine!.Count--;var scope=ChestRigRuntime.Begin(w,ammo,p)!;var before=calculator.Shots.Count;
  var primary=calculator.CreateShot(ammo,new(),new(0,0,1),n,p.ProfileId,w);postfix.Invoke(null,new object[]{calculator,ammo,n,p.ProfileId,w,0,primary});calculator.Shoot(primary);ChestRigRuntime.End(scope);
  var volley=calculator.Shots.Skip(before).ToArray();Check(volley.Length==(n==4?2:1),"actual projectile count on shot "+n);
  if(n!=4)continue;
  Check(volley.Select(b=>b.FragmentIndex).Distinct().Count()==2,"distinct native impact indices");
  foreach(var b in volley){Near(b.Damage,100,"two full-power projectiles");Check(ChestRigRuntime.TryShot(b,out var tracked)&&ReferenceEquals(scope,tracked),"both tracked in same cartridge");ChestRigBallistics.Impact(b);ChestRigBallistics.Impact(b);}
  Check(ProjectileTestEvents.Explosions.Count==2&&ProjectileTestEvents.Visuals==2,"one visible explosion per projectile");
  foreach(var explosion in ProjectileTestEvents.Explosions){Near(explosion.Payload.GetStrength,25,"25% impact damage");Near(explosion.Payload.MaxExplosionDistance,.5,"half-meter radius");Check(explosion.Fallback,"headless/range fallback dispatch");}
 }
});
