 foreach(var count in new[]{2,4,6}){
  var calculator=new EFT.Ballistics.BallisticsCalculator();var primary=new Shot{Ammo=Ammo(),Weapon=new Weapon(),Direction=new(0,0,1),Damage=count>2?70:100,FragmentIndex=0};
  var a=new EffectApplication(main.First()){Active=true,ProjectileCount=count,ProjectileSpreadDegrees=2,ProjectilePattern="horizontal"};ProjectileEffectSpawner.Spawn(calculator,primary,a);var all=calculator.Shots.Append(primary).OrderBy(b=>b.Direction.x).ToArray();
  Check(all.Length==count,"correct even count");Near(all.Sum(b=>b.Direction.x),0,"balanced horizontal spread");for(int i=0;i<count;i++){Near(all[i].Direction.x,-all[count-i-1].Direction.x,"mirrored pair");Near(all[i].Damage,primary.Damage,"damage preserved");Near(all[i].PenetrationPower,primary.PenetrationPower,"penetration preserved");}
  Check(all.Select(b=>b.FragmentIndex).Distinct().Count()==count,"no duplicate native impact IDs");Near(primary.TrajectoryInfo.Velocity.x,primary.StartVelocity.x,"trajectory matches redirected primary");
 }
});
Run("Explosion damage dispatch survives a failed visual and supports both native routes",()=>{
 var(p,w,s)=Equip("TR21-2","pistol");var shot=new Shot{Weapon=w,Ammo=Ammo(),Damage=80,HitPoint=new(0,0,10),HitNormal=new(0,0,-1),PlayerProfileID=p.ProfileId};
 ProjectileTestEvents.FailVisual=true;ProjectileImpactExplosion.Trigger(shot,.25f,.5f);Check(ProjectileTestEvents.Explosions.Count==1,"VFX failure does not cancel damage");Near(ProjectileTestEvents.Explosions[0].Position.z,9.98,"outside impact surface");
 Singleton<GlobalEventDispatcher>.Instance=new();ProjectileImpactExplosion.Trigger(shot,.25f,.5f);Check(!ProjectileTestEvents.Explosions[1].Fallback,"normal native grenade route");Near(ProjectileTestEvents.Explosions[1].Payload.GetStrength,20,"same payload on both paths");
});

Run("Flat Pack adds exactly one row and one column per native pocket with all random storage rolls",()=>{
 foreach(var d in server.Variants.Where(v=>v.RuntimeKey=="TR12-1")){
  Check(d.ChestRigEffect!.EveryGridColumns==1&&d.ChestRigEffect.EveryGridRows==1,"reduced signature");
  var source=Shape((1,2),(1,2),(1,2),(1,2));var before=Node(source).ToJsonString();var result=Node(S.ChestRigStorage.Apply(source,d.ChestRigEffect,d.TemplateId));
  Check(Size(result,0)==(2+d.StorageColumns,3+d.StorageRows),"largest pocket adds only its rolled row/column");for(int i=1;i<4;i++)Check(Size(result,i)==(2,3),"each other pocket is exactly 2x3");
  var area=Enumerable.Range(0,4).Sum(i=>Size(result,i).Item1*Size(result,i).Item2);Check(area==24+2*d.StorageRows+3*d.StorageColumns+d.StorageRows*d.StorageColumns,"total capacity matches one-row/column signature");
  Check(Node(source).ToJsonString()==before,"original IDEA rig remains unchanged");Check(d.EffectText=="Adds 1 column and 1 row to every grid.","display matches actual dimensions");
 }
});
Run("First Responder ignores food and drink without consuming its medical cooldown",()=>{
 foreach(var consumed in new[]{"food","drink"}){
  var(p,w,s)=Equip("AR06-1");p.Physical.HandsStamina.Current=0;
  var item=new Item();item.Components[typeof(FoodDrinkComponent)]=new FoodDrinkComponent();
  var use=new MedicalEffect{HealthController=p.ActiveHealthController,MedItem=item,BodyPart=EBodyPart.Head};
  ChestRigMedical.Begin(use);ChestRigMedical.End(use);
  Near(p.Physical.HandsStamina.Current,0,consumed+" grants no arm stamina");Near(s.DrawCharge,1,consumed+" grants no draw charge");Check(s.Ready,consumed+" leaves medical cooldown ready");
 }
});

EffectStatusModel.Status[] RigRows(Player p)=>EffectStatusModel.Visible(ChestRigRuntime.Statuses(p).Concat(EffectStatusModel.Notices(p.ProfileId,Time.time))).ToArray();
foreach(var key in new[]{"TR13-1","TR14-1","TR16-2","TR17-2","TR33-1","TR33-2","AR01-2","AR04-2","AR05-2","AR05-1","AR14-2","AR16-1","AR16-2"})
Run("Rig conditional status follows gate on/off: "+key,()=>{
 var(p,w,state)=Equip(key);Put(p,EquipmentSlot.Backpack,new Item());
 Check(RigRows(p).Length==0,"inactive condition hidden");
 switch(key){
 case "TR13-1":Put(p,EquipmentSlot.SecondPrimaryWeapon,new Weapon());Put(p,EquipmentSlot.Holster,new Weapon());break;
 case "TR14-1":p.Crouched=true;break;
 case "TR16-2":p.HandsController!.IsAiming=true;p.ProceduralWeaponAnimation.CurrentScope=new(){IsOptic=true};break;
 case "TR17-2":p.SearchController=new();p.SearchController.SearchOperations.Add(new());break;
 case "TR33-1":p.Crouched=true;p.HandsController!.IsAiming=true;break;
 case "TR33-2":w.Children.Add(new Silencer());break;
 case "AR01-2":state.StillSeconds=3;break;
 case "AR04-2":var effect=new LightBleeding();var dressing=new Item();var treatment=new HealthEffectsComponent();treatment.DamageEffects[EDamageEffectType.LightBleeding]=new();dressing.Components[typeof(HealthEffectsComponent)]=treatment;ChestRigMedical.Uses[new object()]=new(){State=state,Item=dressing,Part=EBodyPart.Chest,Bleeds={effect}};break;
 case "AR05-2":state.Bleeds[new LightBleeding()]=Time.time+10;break;
 case "AR05-1":w.Magazine!.Count=5;state.Reloading=true;break;
 case "AR14-2":p.HandsController=new Player.BaseKnifeController();break;
 case "AR16-1":Put(p,EquipmentSlot.Backpack,null);break;
 case "AR16-2":p.ActiveHealthController.Fractured.Add(EBodyPart.LeftLeg);break;
 }
 var row=RigRows(p).Single();Check(row.Active,"actual conditional benefit visible");
 p.Crouched=false;p.HandsController=new Player.FirearmController{Player=p,Item=w};p.SearchController=null;w.Children.Clear();state.StillSeconds=0;state.Reloading=false;state.Bleeds.Clear();ChestRigMedical.Uses.Clear();Put(p,EquipmentSlot.SecondPrimaryWeapon,null);Put(p,EquipmentSlot.Holster,null);Put(p,EquipmentSlot.Backpack,new Item());p.ActiveHealthController.Fractured.Clear();
 Check(RigRows(p).Length==0,"condition ending clears row");Put(p,EquipmentSlot.TacticalVest,null);Check(!ChestRigRuntime.Statuses(p).Any(),"unequipped condition absent");
});
Run("Tree Line bolt-cycle charge stays visible after its shorter reload timer expires",()=>{
 var(p,w,state)=Equip("TR24-2");state.CycleCharge=1.75f;ChestRigRuntime.ArmReload(state,1.6f);Time.time+=5;
 Check(RigRows(p).Single().Detail=="Next bolt cycle ready","real remaining charge retained");state.CycleCharge=1;Check(!RigRows(p).Any(),"consuming charge clears row");
});
