Run("Unconditional rig signatures do not show permanent random or signature rows",()=>{
 foreach(var key in new[]{"TR04-1","TR05-1","TR07-2","TR12-1","TR19-2","AR07-1","AR09-2","AR13-2","AR20-1","AR21-1","AR21-2","AR25-2"}){var(p,w,state)=Equip(key);Check(!RigRows(p).Any(),"permanent hidden: "+key);}
