var bagCases=new[]{"BP02-1","BP05-2","BP06-2","BP07-3","BP08-3","BP11-2","BP12-1","BP13-1","BP14-3","BP15-1","BP16-1","BP17-1","BP22-3","BP23-3","BP24-1","BP24-2","BP26-1","BP27-2","BP28-3","BP30-1","BP31-2","BP34-1","BP35-3","BP37-2","BP38-1","BP39-1","BP40-2","BP41-2","BP41-3","BP45-2"};
(Player P,Weapon W,BackpackRuntime.State S) BagFixture(string key){var p=new Player();var d=client.Variants.First(v=>v.BackpackEffect?.Key==key&&v.StorageRollVersion==0);var bag=new CompoundItem{StringTemplateId=d.TemplateId};Put(p,EquipmentSlot.Backpack,bag);var w=new Weapon{Magazine=new(){Count=30,MaxCount=30}};p.HandsController=new Player.FirearmController{Item=w,Player=p};Put(p,EquipmentSlot.FirstPrimaryWeapon,w);return(p,w,BackpackRuntime.Get(p)!);}
EffectStatusModel.Status[] BagRows(BackpackRuntime.State state){var rows=new List<EffectStatusModel.Status>();BackpackEffectStatus.Add(rows,state);return EffectStatusModel.Visible(rows).ToArray();}
foreach(var key in bagCases)Run("Backpack status uses its real gate and ends: "+key,()=>{
 var(p,w,state)=BagFixture(key);var clock=Time.time;
 switch(key){
 case "BP02-1":p.MovementContext.IsSprintEnabled=true;break;
 case "BP05-2":p.ActiveHealthController.Hydration.Current=0;break;
 case "BP06-2":for(int i=0;i<2;i++){var food=new Item{StringTemplateId="food"+i};food.Components[typeof(FoodDrinkComponent)]=new FoodDrinkComponent();state.Bag.Children.Add(food);}break;
 case "BP07-3":p.ActiveHealthController.Destroyed.Add(EBodyPart.LeftLeg);break;
 case "BP08-3":Put(p,EquipmentSlot.FirstPrimaryWeapon,null);break;
 case "BP11-2":case "BP28-3":p.MovementContext.IsInPronePose=true;break;
 case "BP12-1":state.Record.Arm("lootSprint",15);break;
 case "BP13-1":p.InputDirection=new();break;
 case "BP14-3":state.ColdCharge=true;break;
 case "BP15-1":((EFT.Toggle)((EFT.Vision)p.NightVisionObserver).Component).IsOn=true;break;
 case "BP16-1":state.JumpCharged=true;break;
 case "BP17-1":state.Record.Arm("fallSpeed",15);break;
 case "BP22-3":p.WoodsFlag=true;break;
 case "BP23-3":state.Record.Arm("bleed:Chest",120);break;
 case "BP24-1":BackpackRuntime.Day=true;break;
 case "BP24-2":state.Record.Categories.Add("barter");break;
 case "BP26-1":for(int i=0;i<21;i++)state.Record.Templates.Add("item"+i);break;
 case "BP27-2":w.WeapClass="sniperRifle";break;
 case "BP30-1":p.AimingLoaded=true;break;
 case "BP31-2":state.Record.Distance[key]=1000;break;
 case "BP34-1":p.MovementContext.IsSprintEnabled=false;break;
 case "BP35-3":state.Record.Arm("meleeReach",20);break;
 case "BP37-2":state.Record.Arm("milk",180);break;
 case "BP38-1":p.SearchController=new();p.SearchController.SearchOperations.Add(new(){Item=new(){IsCorpse=true}});break;
 case "BP39-1":w.WeapClass="pistol";Put(p,EquipmentSlot.FirstPrimaryWeapon,null);break;
 case "BP40-2":state.Record.Arm("traversal:sprint",5);break;
 case "BP41-2":state.Bag.CompartmentsFull=true;break;
 case "BP41-3":state.Record.Arm("firstItem",180);break;
 case "BP45-2":state.Bag.GridFull=true;break;
 }
 Check(BagRows(state).Single().Active,"active gate visible");
 p.MovementContext.IsSprintEnabled=key=="BP34-1";p.MovementContext.IsInPronePose=false;p.InputDirection=new(1,0);p.ActiveHealthController.Hydration.Current=100;state.Bag.Children.Clear();p.ActiveHealthController.Destroyed.Clear();Put(p,EquipmentSlot.FirstPrimaryWeapon,w);state.ColdCharge=state.JumpCharged=state.JumpSafe=false;((EFT.Toggle)((EFT.Vision)p.NightVisionObserver).Component).IsOn=false;p.WoodsFlag=p.AimingLoaded=false;BackpackRuntime.Day=false;state.Record.Categories.Clear();state.Record.Templates.Clear();state.Record.Distance.Clear();w.WeapClass="assaultRifle";p.SearchController=null;state.Bag.CompartmentsFull=state.Bag.GridFull=false;Time.time=clock+181;
 Check(!BagRows(state).Any(),"condition or timer end hides status");
});
Run("All 67 backpack designs are classified as conditional, cooldown, proc or permanent",()=>{
 var exceptions=bagCases.Concat(EffectStatusModel.Cooldowns.Select(c=>c.Key)).Concat(new[]{"BP18-2","BP36-1","BP37-3","BP14-3","BP23-1","BP42-1"}).ToHashSet();
 foreach(var d in client.Variants.Where(v=>v.BackpackEffect!=null&&v.StorageRollVersion==0)){if(exceptions.Contains(d.RuntimeKey))continue;var(p,w,state)=BagFixture(d.RuntimeKey);Check(!BagRows(state).Any(),"unconditional storage/access/stat modifier hidden: "+d.RuntimeKey);}
});


