Run("Backpack drop buffs retain real active and cooldown phases without a worn-item requirement",()=>{var timers=new Dictionary<string,float>{{"cd:BP10-3",160},{"throwDistance",115}};var row=EffectStatusModel.Collect(timers,100).Single();Check(row.Active&&row.Seconds==15&&row.Ready==60,"Sling Away remains active after dropping the bag");row=EffectStatusModel.Collect(timers,115).Single();Check(!row.Active&&row.Ready==45,"buff expires while real cooldown remains");Check(!EffectStatusModel.Collect(timers,160).Any(),"exact final expiry");});

Console.WriteLine($"Chest rigs: {cases-failures}/{cases} cases passed; {assertions} assertions; {failures} failures.");return failures==0?0:1;
